function load(name, mocks) {
  const url = new URL(`../src/${name}`, import.meta.url);
  const source = readFileSync(url, 'utf8').replace(/^import ['"][^'"]+\.css['"];?\s*$/gm, '');
  const {code} = transformSync(source, {loader: 'jsx', format: 'cjs', jsx: 'transform'});
